#define SPRITE_UPDATE_RECORD_BYTES 10
/* This is a game error value, not a VGA or DOS service number. */
#define IMAGE_UPDATE_LIST_OVERFLOW_ERROR 0x407

/* Observed at stride 10 in the sprite command writers: address, x/y, zeroed word. */
struct SpriteUpdateListEntry {
    unsigned char *sprite_frame;
    short x;
    short y;
    short reserved;
};

/* _DATA [0x746c,0x7474) */
short image_buffer_error_code = 0;
short image_color_depth = 8;
unsigned int image_buffer_record_limit = 0;

int rotate_image_buffer(void) {
    active_video_page_buffer = image_page_back_buffer;
    image_page_back_buffer = front_image_page_buffer;
    front_image_page_buffer = active_video_page_buffer;
    return front_image_page_buffer;
}

/* Keep two image pages available for drawing and display. */
void set_image_pages(unsigned char *sprite_update_list, int record_limit, int color_depth,
                     unsigned char *front_page_buffer, unsigned char *back_page_buffer) {
    image_buffer_record_limit = record_limit;
    image_update_list_start = sprite_update_list;
    image_buffer_cursor = image_update_list_start;
    image_color_depth = color_depth;
    if (image_color_depth == 4) {
        front_image_page_buffer = front_page_buffer;
        active_video_page_buffer = front_image_page_buffer;
        *(short *)active_video_page_buffer = 0;
        image_page_back_buffer = back_page_buffer;
        active_video_page_buffer = image_page_back_buffer;
        *(short *)active_video_page_buffer = 0;
    }
}

void clear_and_rotate_image_buffer(void) {
    ((struct SpriteUpdateListEntry *)image_buffer_cursor)->sprite_frame = 0;
    replay_sprite_update_list_entry(rotate_image_buffer());
}

void render_image_region(int x, int y) {
    process_sprite_update_list_entry(x, y, image_update_list_start, active_video_page_buffer);
    *(short *)active_video_page_buffer = 0;
    /* Preserve the original guard's divide-then-times-ten comparison. */
    if ((image_buffer_cursor - image_update_list_start) / SPRITE_UPDATE_RECORD_BYTES >
        image_buffer_record_limit * SPRITE_UPDATE_RECORD_BYTES)
        image_buffer_error_code = IMAGE_UPDATE_LIST_OVERFLOW_ERROR;
    image_buffer_cursor = image_update_list_start;
}

void redraw_image_region(int x, int y) {
    clear_and_rotate_image_buffer();
    render_image_region(x, y);
}

void render_image_with_options(int display_state, int color_depth, int render_arg1, int render_arg2, int render_arg3) {
    int previous_display_state = drawpage;
    int previous_color_depth = image_color_depth;
    image_color_depth = color_depth;
    drawpage = display_state;
    draw_bob_sprite_entry(render_arg1, render_arg2, render_arg3);
    drawpage = previous_display_state;
    image_color_depth = previous_color_depth;
}
